package com.priperi;
import android.app.*;import android.content.*;import android.graphics.Rect;import android.os.*;import android.view.*;import android.widget.*;import androidx.test.core.app.*;import androidx.test.ext.junit.runners.AndroidJUnit4;import androidx.test.platform.app.InstrumentationRegistry;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import java.io.*;import java.util.*;import java.util.concurrent.*;import static org.junit.Assert.*;
@RunWith(AndroidJUnit4.class) public class ConversationAlertsTest {
 private Context context;private Vault peer;private String uid,peerId,gid;private final String password="Alerts-Password-2026!";
 private <T>T local(Repository.Job<T> job)throws Exception{CompletableFuture<T> done=new CompletableFuture<>();Repository.local(context,v->{try{return job.run(v);}catch(Throwable e){done.completeExceptionally(e);return null;}},done::complete,e->done.completeExceptionally(new AssertionError(e)));return done.get(40,TimeUnit.SECONDS);}
 @Before public void setup()throws Exception{context=ApplicationProvider.getApplicationContext();assertTrue(BuildConfig.ALLOW_TEST_DEVICES);assertTrue(BuildConfig.BACKEND_URL.startsWith("http://10.0.2.2:"));context.getSharedPreferences("notification_access",0).edit().putBoolean("asked",true).commit();Repository.reset();String suffix=UUID.randomUUID().toString().substring(0,8);peer=new Vault(context,"qa_alertpeer_"+suffix);shell("pm grant "+context.getPackageName()+" android.permission.POST_NOTIFICATIONS");local(v->{assertNull(v.account());uid=Session.continueAccount(v,"qa_alert_"+suffix,password).getString("uid");peerId=Session.continueAccount(peer,"qa_ap_"+suffix,password).getString("uid");TestIdentityTrust.pin(peer,Repository.call(peer,"lookupUser",new JSONObject().put("uid",uid)));Session.restore(v);TestIdentityTrust.pin(v,Repository.call(v,"lookupUser",new JSONObject().put("uid",peerId)));v.setSetting("notifications",true);return true;});PriperiApp.foreground=false;Notices.clear(context);}
 @After public void cleanup()throws Exception{local(v->{Session.restore(peer);Session.resetAccount(peer);Session.restore(v);Session.resetAccount(v);Repository.eraseLocal(v);return true;});peer.destroy();context.getSystemService(android.app.job.JobScheduler.class).cancel(PushSyncService.JOB);Repository.reset();Notices.clear(context);PriperiApp.foreground=false;}
 private int notices(){return context.getSystemService(NotificationManager.class).getActiveNotifications().length;}
 private void barrier()throws Exception{local(v->true);InstrumentationRegistry.getInstrumentation().waitForIdleSync();}
 private void inbox()throws Exception{new SyncEngine((SyncEngine.Progress)null).inbox();barrier();}
 private void fromPeer(String body)throws Exception{local(v->{Session.restore(peer);Repository.send(peer,uid,body);Repository.sync(peer);Session.restore(v);return true;});}
 @Test public void directMuteSilencesSavedMessagesReplayDoesNotAlertAndUnmuteRestoresGenericAlerts()throws Exception{local(v->{v.mute(peerId,-1);return true;});fromPeer("Muted private content");inbox();assertEquals(1,(int)local(v->v.messages(peerId).size()));assertEquals(0,notices());local(v->{v.mute(peerId,0);return true;});fromPeer("Visible only inside vault");inbox();assertEquals(1,notices());Notification shown=context.getSystemService(NotificationManager.class).getActiveNotifications()[0].getNotification();assertFalse(shown.extras.toString().contains("Visible only inside vault"));assertFalse(shown.extras.toString().contains(peerId));Notices.clear(context);inbox();assertEquals(0,notices());local(v->{v.mute(peerId,System.currentTimeMillis()-1);assertFalse(v.muted(peerId));return true;});}
 @Test public void groupMuteStillReceivesAndUnmuteAllowsAlerts()throws Exception{gid=UUID.randomUUID().toString();String invite=UUID.randomUUID().toString();local(v->{Session.restore(peer);GroupRepository.create(peer,gid,"Muted team");GroupRepository.action(peer,"inviteGroupMember",new JSONObject().put("groupId",gid).put("uid",uid).put("id",invite));Session.restore(v);Repository.sync(v);GroupRepository.action(v,"acceptGroupInvite",new JSONObject().put("id",invite));Repository.sync(v);v.mute("group:"+gid,-1);Session.restore(peer);Repository.sync(peer);TestIdentityTrust.sendGroup(peer,gid,"Quiet group message");Repository.sync(peer);Session.restore(v);return true;});inbox();assertEquals(1,(int)local(v->v.messages("group:"+gid).size()));assertEquals(0,notices());local(v->{v.mute("group:"+gid,0);Session.restore(peer);TestIdentityTrust.sendGroup(peer,gid,"Group unmuted");Repository.sync(peer);Session.restore(v);return true;});inbox();assertEquals(1,notices());}
 @Test public void globalOptOutAndForegroundSuppressAlertsAndStoredMuteSurvivesReload()throws Exception{local(v->{v.setSetting("notifications",false);v.mute(peerId,-1);return true;});Notices.received(uid,Set.of(peerId));barrier();assertEquals(0,notices());Repository.reset();local(v->{assertTrue(v.muted(peerId));v.setSetting("notifications",true);v.mute(peerId,0);return true;});PriperiApp.foreground=true;Notices.received(uid,Set.of(peerId));barrier();assertEquals(0,notices());PriperiApp.foreground=false;Notices.received(UUID.randomUUID().toString(),Set.of(peerId));barrier();assertEquals(0,notices());}
 @Test public void chatAllowanceSitsAboveComposerAndMuteButtonWorksForDirectAndGroup()throws Exception{try(ActivityScenario<ChatActivity> screen=ActivityScenario.launch(new Intent(context,ChatActivity.class).putExtra("peer",peerId))){await(screen,a->desc(a.root,"Mute conversation")!=null&&find(a.root,"messages left")!=null);screen.onActivity(a->{View notice=find(a.root,"messages left"),input=findInput(a.root),mute=desc(a.root,"Mute conversation");Rect n=new Rect(),i=new Rect();assertTrue(notice.getGlobalVisibleRect(n));assertTrue(input.getGlobalVisibleRect(i));assertTrue("Allowance must be immediately above composer",n.bottom<=i.top&&i.top-n.bottom<Ui.dp(a,90));mute.performClick();});AccountControlsFlowTest.click("Until I turn it back on");await(screen,a->desc(a.root,"Unmute conversation")!=null);assertTrue(local(v->v.muted(peerId)));screen.onActivity(a->desc(a.root,"Unmute conversation").performClick());AccountControlsFlowTest.click("Unmute");await(screen,a->desc(a.root,"Mute conversation")!=null);assertFalse(local(v->v.muted(peerId)));}}
 @Test public void systemManagedPushJobRestoresSessionAndSavesMutedMessagesWithoutAlert()throws Exception{
  local(v->{v.mute(peerId,-1);return true;});fromPeer("Job saved muted message");Repository.reset();PushSyncService.schedule(context);shell("cmd jobscheduler run -f "+context.getPackageName()+" "+PushSyncService.JOB);
  boolean saved=false;for(int i=0;i<150;i++){if(local(v->v.messages(peerId).size())==1){saved=true;break;}SystemClock.sleep(100);}assertTrue("System job did not save the message",saved);barrier();assertEquals(0,notices());
  local(v->{v.setSetting("notifications",false);return true;});fromPeer("Global alerts disabled");PushSyncService.schedule(context);shell("cmd jobscheduler run -f "+context.getPackageName()+" "+PushSyncService.JOB);SystemClock.sleep(300);assertEquals(1,(int)local(v->v.messages(peerId).size()));assertEquals(0,notices());
 }
 private interface Ready{boolean check(ChatActivity a);}private static void await(ActivityScenario<ChatActivity> s,Ready r){for(int i=0;i<150;i++){boolean[] ready={false};s.onActivity(a->ready[0]=a.root.isShown()&&r.check(a));if(ready[0])return;SystemClock.sleep(50);}fail("Chat controls stayed unavailable");}
 private static View find(View v,String text){if(v instanceof TextView&&((TextView)v).getText().toString().contains(text))return v;if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++){View n=find(g.getChildAt(i),text);if(n!=null)return n;}}return null;}
 private static View desc(View v,String text){if(v.getContentDescription()!=null&&text.contentEquals(v.getContentDescription()))return v;if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++){View n=desc(g.getChildAt(i),text);if(n!=null)return n;}}return null;}
 private static View findInput(View v){if(v instanceof EditText)return v;if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++){View n=findInput(g.getChildAt(i));if(n!=null)return n;}}return null;}
 private static void shell(String command)throws Exception{try(ParcelFileDescriptor p=InstrumentationRegistry.getInstrumentation().getUiAutomation().executeShellCommand(command);InputStream in=new FileInputStream(p.getFileDescriptor())){while(in.read()!=-1){}}}
}
